// 获取输入数据（来自 SQL 节点）
const inputData = $('sql').first().json.data;
// 获取单位说明
const unitInfo = $input.first().json.data;

// 初始化两个输出
let convertedData = []; // 字符串数组，供 Switch 节点使用（含单位和链接）
let resources = [];     // 对象数组，供前端使用（含单位和链接）

// 基础链接
const BASE_URL = "https://germplasm.cgris.net/geneshare/seed/seed/basicquery?querycondition=";

// 解析单位信息
let unitMap = {};
if (unitInfo && typeof unitInfo === 'string') {
  const unitLines = unitInfo.split('\n').filter(line => line.includes('：'));
  unitLines.forEach(line => {
    const [field, unit] = line.split('：');
    if (field && unit) {
      unitMap[field.trim()] = unit.trim();
    }
  });
}

// 处理数组情况
if (Array.isArray(inputData)) {
  // 1. 先生成 convertedData：为每个 item 添加单位信息和链接后转字符串
  convertedData = inputData.map(item => {
    if (typeof item === 'object' && item !== null) {
      // 创建带单位信息和链接的新对象
      let itemWithUnitsAndLink = { ...item };

      // 添加 purchase_link
      const accessionNumber = item["统一编号"] || item.accession_number || item.germplasm_id || '';
      const purchase_link = accessionNumber 
        ? `${BASE_URL}${encodeURIComponent(accessionNumber)}`
        : null;
      itemWithUnitsAndLink.purchase_link = purchase_link;

      // 根据单位说明为数值型字段添加单位
      Object.keys(unitMap).forEach(field => {
        if (itemWithUnitsAndLink.hasOwnProperty(field)) {
          const value = itemWithUnitsAndLink[field];
          if (typeof value === 'number' || (!isNaN(value) && value !== null && value !== undefined && value !== '')) {
            itemWithUnitsAndLink[field] = `${value} ${unitMap[field]}`;
          }
        }
      });

      return JSON.stringify(itemWithUnitsAndLink);
    }
    return String(item);
  });

  // 2. 再生成 resources：为每个 item 添加单位信息和 purchase_link
  resources = inputData.map(item => {
    if (typeof item === 'object' && item !== null) {
      // 创建带单位信息的新对象
      let itemWithUnits = { ...item };

      // 添加 purchase_link
      const accessionNumber = item["全国统一编号"] || item.accession_number || item.germplasm_id || '';
      const purchase_link = accessionNumber 
        ? `${BASE_URL}${encodeURIComponent(accessionNumber)}`
        : null;

      // 根据单位说明为数值型字段添加单位
      Object.keys(unitMap).forEach(field => {
        if (itemWithUnits.hasOwnProperty(field)) {
          const value = itemWithUnits[field];
          if (typeof value === 'number' || (!isNaN(value) && value !== null && value !== undefined && value !== '')) {
            itemWithUnits[field] = `${value} ${unitMap[field]}`;
          }
        }
      });

      return { ...itemWithUnits, purchase_link };
    }
    return item;
  });

} 
// 处理单个对象
else if (typeof inputData === 'object' && inputData !== null) {
  // convertedData 用带单位信息和链接的对象转字符串
  let itemWithUnitsAndLink = { ...inputData };

  // 添加 purchase_link
  const accessionNumber = inputData["统一编号"] || inputData.accession_number || inputData.germplasm_id || '';
  const purchase_link = accessionNumber 
    ? `${BASE_URL}${encodeURIComponent(accessionNumber)}`
    : null;
  itemWithUnitsAndLink.purchase_link = purchase_link;

  // 根据单位说明为数值型字段添加单位
  Object.keys(unitMap).forEach(field => {
    if (itemWithUnitsAndLink.hasOwnProperty(field)) {
      const value = itemWithUnitsAndLink[field];
      if (typeof value === 'number' || (!isNaN(value) && value !== null && value !== undefined && value !== '')) {
        itemWithUnitsAndLink[field] = `${value} ${unitMap[field]}`;
      }
    }
  });

  convertedData = [JSON.stringify(itemWithUnitsAndLink)];

  // resources 添加单位信息和链接
  let itemWithUnits = { ...inputData };

  // 根据单位说明为数值型字段添加单位
  Object.keys(unitMap).forEach(field => {
    if (itemWithUnits.hasOwnProperty(field)) {
      const value = itemWithUnits[field];
      if (typeof value === 'number' || (!isNaN(value) && value !== null && value !== undefined && value !== '')) {
        itemWithUnits[field] = `${value} ${unitMap[field]}`;
      }
    }
  });

  resources = [{ ...itemWithUnits, purchase_link }];

} 
// 其他基本类型
else {
  convertedData = [String(inputData)];
  resources = [];
}

// 返回结果
return [{
  json: {
    convertedData,
    resources
  }
}];

