// ========================
// 1. 安全获取输入值 & 数据清洗
// ========================
const contextNode = $("When Executed by Another Workflow").last()?.json;
const extractionNode = $("Extract from File2").item?.json;

// 辅助函数：防止对象/数组变成 [object Object]
const safeStringify = (val, defaultVal) =>
  (typeof val === 'object') ? JSON.stringify(val) : (val || defaultVal);

// ✅ 修改点：从第一个触发工作流的节点中获取 context_query
const rawContextQuery = $("When Executed by Another Workflow").first()?.json?.context_query;
const prompt = rawContextQuery 
  ? String(rawContextQuery).replace(/\n+/g, ' ').trim() 
  : '无上下文查询信息';

const varieties = contextNode?.varieties || '未知作物';
const datatable = `${varieties}_data`; // 假设表名规则
const mining = contextNode?.mining?.replace(/\n+/g, ' ') || '查询建议缺失';
const keywords = contextNode?.keywords || '';

// 字段与规则 (使用 safeStringify)
const fieldList = safeStringify(extractionNode?.data, '字段信息缺失');
const sqlRules = safeStringify($("Extract from File4").item?.json?.data, '字段规范缺失');

// 获取用户类型（默认 B 类 - 普通用户）
const userType = contextNode?.userType || 'B';

// ========================
// 2. 商业模式与权限逻辑核心
// ========================
// 获取商业模式标识 (兼容多层级结构和不同类型)
const rawInput = $("When Executed by Another Workflow")?.first()?.json;
const commercialModeRaw =
  rawInput?.commercialMode ??
  rawInput?.body?.commercialMode ??
  rawInput?.data?.commercialMode ??
  false;

// 兼容 true, "true", 1, "1"
const isCommercialMode = [true, 'true', '1', 1].includes(commercialModeRaw);

let accessCondition = "1=1";
let accessDescription = "";
let needsPermissionFilter = false; // 标记是否需要在 SQL 中强制加 WHERE

if (isCommercialMode) {
  // 商业版：全开
  accessDescription = "✅ [商业版环境] 全库资源开放，无行级权限限制。";
  needsPermissionFilter = false;
} else {
  // 非商业版：基于用户类型的细分
  switch (userType) {
    case 'C':
      // C类：特权用户（全量查询，含 A/B/不公开）
      accessDescription = "🚀 [C类用户] 管理员/特权身份，拥有全库访问权限，无需过滤共享类型。";
      needsPermissionFilter = false;
      break;

    case 'A':
      // A类：标准用户（A + B）
      accessCondition = "`共享类型` IN ('A类', 'B类')";
      accessDescription = "当前为【A类用户】，仅可访问 A类 + B类资源。";
      needsPermissionFilter = true;
      break;

    case 'B':
    case 'D':
      // B类 & D类（游客）：仅 B类
      const typeName = userType === 'D' ? "游客" : "普通用户";
      accessCondition = "`共享类型` = 'B类'";
      accessDescription = `⚠️ [${userType}类用户 - ${typeName}] 严格限制：仅可访问 \`共享类型\` 为 'B类' 的公开资源。`;
      needsPermissionFilter = true;
      break;

    default:
      // 兜底逻辑：强制最低权限
      accessCondition = "`共享类型` = 'B类'";
      accessDescription = "用户类型未知，系统强制按【B类】最低权限处理。";
      needsPermissionFilter = true;
  }
}

// ========================
// 3. 构造 User Prompt
// ========================
const userPrompt = [
  `提示：${prompt}`,
  `用户任务相关作物类别：${varieties}`,
  `${varieties}的数据表：${datatable}`,
  `用户类型：${userType}类`,
  `权限说明：${accessDescription}`,
  `字段信息如下：\n${fieldList}`,
  `查询意见是：${mining}`
].join('\n');

// ========================
// 4. 构造 System Prompt (动态权限注入)
// ========================
// 动态生成权限说明部分
let accessRuleSection = "";
if (needsPermissionFilter) {
  // 强制限制
  accessRuleSection = `✅ 新增硬性规则（权限控制）：\n${accessDescription}\n因此，**必须**在 WHERE 子句中加入：(${accessCondition})，作为最基础的准入条件，不达标者直接排除。`;
} else {
  // 全量开放
  accessRuleSection = `✅ 当前为商业版数据库或特权模式，无“共享类型”字段限制，所有用户均可访问全部资源，**无需**添加相关权限过滤。`;
}

const systemPrompt = [
  `你是一个经验丰富的 MySQL 数据库专家，擅长基于用户意图自动生成符合 MYSQL 规范的 SQL 查询语句，查询表 ${datatable}，并能根据复杂的评分标准、属性规则和字段限定公平打分，从 ${varieties} 种质资源数据库中挖掘出最优资源。`,
  `请围绕关键词中的字段指标构造 SQL 语句，关键词是：${keywords}。\n`,
  `【你的任务】`,
  `根据用户输入的任务，匹配表中字段，结合查询建议，生成一条合法、可执行、具评分逻辑的 SQL 查询语句。`,
  `注意：SELECT 子句中必须包含“全国统一编号”和“种质名称”字段，确保每条记录可追溯。\n`,
  `### 🔐 权限与安全控制`,
  accessRuleSection,
  `\n`,
  `### 📋 表结构与规范`,
  `查询表 ${datatable} 有以下需要注意的事项：`,
  `${sqlRules}\n`,

  // 🎯 新增：阶梯赋分与严惩劣质数据逻辑
  `### 🎯 智能筛选与阶梯赋分逻辑（核心）`,
  `在构建 SELECT 中的评分字段（如 total_score）时，必须对与关键词 ${keywords} 相关的指标进行高颗粒度的阶梯式加权打分：`,
  `1. **高颗粒度阶梯赋分法**：数值型字段必须至少划分 4~5 个以上的评分梯度（最优区间得 0 分，偏离越大，分值惩罚呈指数级上升）。`,
  `   - ✅ 正确要求：例如目标值为 70-120，则 70-120 得 0 分；60-130 得 15 分；50-140 得 40 分；极端偏离的值（如 10-20）必须给予极高惩罚（如 200 分或 300 分）。`,
  `   - ❌ 错误示范：只写一个理想区间，剩下的全归入 ELSE 罚一个小分数。`,
