// ============================================================
// 1. 获取输入数据
// ============================================================

// 1.1 获取原始资源数据
let rawResources = [];
try {
    const nodeOutput = $('转换成字符串格式');
    if (nodeOutput && nodeOutput.first) {
        rawResources = nodeOutput.first().json?.resources || [];
    }
} catch (e) {
    console.log("Fallback to $input for resources");
    rawResources = $input.first().json?.resources || [];
}

// 1.2 直接获取作物字段集名称（如 "wheat_data"）
let dataTypeKey = 'wheat_data'; // 默认兜底
try {
