    };

    // === 关键：即使 idealMin/idealMax 为 null 也要显示字段 ===
    const idealRange = llmMeta.ideal_ranges[key];
    if (Array.isArray(idealRange)) {
        dim.idealMin = idealRange[0]; // 允许 null
        dim.idealMax = idealRange[1]; // 允许 null
    }

    return dim;
});

// ============================================================
// 7. 返回结果（不包含 cropDataKey）
// ============================================================
return {
