// ==========================================
// 1️⃣ 核心修复：SQL 语法结构修复函数
// ==========================================
function fixSqlSyntax(sql) {
  if (!sql) return "";

  // 🚨 修复 1: 补全缺失的 CASE WHEN
  // 针对错误模式: IFNULL(字段,0) = 0 THEN ... END
  // 许多 LLM 会在写长公式时漏掉开头的 CASE WHEN
  sql = sql.replace(
    /(CASE\s+WHEN\s+)?(IFNULL\s*\([^)]+\)\s*[=<>!]+\s*\d+\s+THEN)/gi,
    (match, prefix, body) => {
      // 如果前面已经有 CASE WHEN，则保持原样；否则补上
      if (prefix && prefix.trim().length > 0) return match;
      return `CASE WHEN ${body}`;
    }
  );

  // 🚨 修复 2: 补全简单的比较逻辑缺失 CASE WHEN
  // 针对错误模式: + 粗蛋白 >= 15 THEN ... (漏了 CASE WHEN)
  // 这里的正则识别 "+ 汉字/字母 >= 数字 THEN" 这种模式
  sql = sql.replace(
    /(\+\s*)([\u4e00-\u9fa5a-zA-Z0-9_]+\s*[=<>!]+\s*[\d.]+\s+THEN)/gi,
    (match, sign, body) => {
      return `${sign} CASE WHEN ${body}`;
    }
  );

  return sql;
}

// ==========================================
// 2️⃣ 辅助工具：相似度计算 (保留你原有的逻辑)
// ==========================================
function levenshtein(a, b) {
  const m = a.length, n = b.length;
  const dp = Array.from({ length: n + 1 }, (_, j) => j);
  for (let i = 1; i <= m; i++) {
    let prev = i, tmp;
    for (let j = 1; j <= n; j++) {
      tmp = dp[j];
      dp[j] = a[i - 1] === b[j - 1]
        ? prev
        : Math.min(dp[j] + 1, dp[j - 1] + 1, prev + 1);
      prev = tmp;
    }
  }
  return dp[n];
}

function similarity(a, b) {
  const len = Math.max(a.length, b.length);
  return len ? 1 - levenshtein(a, b) / len : 1;
}

