// SQL 提取正则
const sqlRegex = /(?:^|\s)(?:```)?((?:SELECT\s.+?\sFROM)[^;]*)(?:;)?(?:```)?/gis;

// 修复 WHEN 与字段粘连（如 WHEN字段 → WHEN 字段）
function fixWhenSpacing(sql) {
  return sql.replace(/\bWHEN([^\s(=><!]+)/g, 'WHEN $1');
}

// 修复表达式中嵌套 AS（如 IFNULL(...) AS name + ...）
function fixInnerAs(sql) {
  return sql.replace(/(\bIFNULL\s*\([^()]+\))\s+AS\s+\w+\s*([+\-),\n])/g, '$1$2');
}

// 移除非法括号表达式中嵌套 AS（(expr AS alias) → expr AS alias）
function fixParenAs(sql) {
  return sql.replace(/\(\s*([^()]+?)\s+AS\s+(\w+)\s*\)/g, (_, expr, alias) => {
    return `${expr} AS ${alias}`;
  });
}

// 修复 SELECT *, (...) AS alias → SELECT *, expr AS alias
function fixSelectWrapper(sql) {
  return sql.replace(/SELECT\s*\*\s*,\s*\((.+?)\)\s+AS\s+(\w+)/is, (_, expr, alias) => {
    return `SELECT *, ${expr} AS ${alias}`;
  });
}

// 移除非法元组 (expr1, expr2, expr3)
function fixIllegalTuples(sql) {
  return sql.replace(/SELECT\s+\*,\s*\(([^()]+?,[^()]+?)\)/gi, (_, inner) => {
    return `SELECT *, ${inner}`;
  });
}

