// 相似度比较函数
function levenshtein(a, b) {
  const m = a.length, n = b.length;
  const dp = Array.from({ length: n + 1 }, (_, j) => j);
  for (let i = 1; i <= m; i++) {
    let prev = i, tmp;
    for (let j = 1; j <= n; j++) {
      tmp = dp[j];
      dp[j] = a[i - 1] === b[j - 1] ? prev : Math.min(dp[j] + 1, dp[j - 1] + 1, prev + 1);
      prev = tmp;
    }
  }
  return dp[n];
}

function similarity(a, b) {
  const len = Math.max(a.length, b.length);
  return len ? 1 - levenshtein(a, b) / len : 1;
}
// 注释区域屏蔽
function wrapComments(sql) {
  const commentMap = new Map();
  let counter = 0;
  sql = sql.replace(/--.*$/gm, (m) => {
    const key = `__COMMENT_${counter++}__`;
    commentMap.set(key, m);
    return key;
  });
  return { sql, commentMap };
}

// 注释区域还原
function unwrapComments(sql, commentMap) {
  for (const [key, value] of commentMap.entries()) {
    sql = sql.replace(key, value);
  }
  return sql;
}

// 字段名修复函数
function fixFieldNames(sql) {
  const aliasSet = new Set();
  sql.replace(/\bAS\s+([\u4e00-\u9fa5]{2,8})/g, (_, alias) => aliasSet.add(alias));

  return sql.replace(/([^\w])([\u4e00-\u9fa5]{2,8}?)(?=[\s=<>),;])/g, (m, pre, fld) => {
    if (aliasSet.has(fld) || correctFields.includes(fld)) return m;

    let best = fld;
    let bestScore = 0;

    for (const cf of correctFields) {
      // 避免将长字段替换为短字段（如：杆锈反应型 → 芒）
      if (Math.abs(cf.length - fld.length) > 2) continue;

      const sc = similarity(fld, cf);

      // 加强对“反应型”等关键词字段的匹配
      const keywordBoost = (fld.endsWith('反应型') && cf.endsWith('反应型')) ? 0.2 : 0;

      const totalScore = sc + keywordBoost;
      if (totalScore > bestScore && totalScore > 0.6) {
        bestScore = totalScore;
        best = cf;
      }
    }

    return `${pre}${best}`;
  });
}


// 清洗主函数
function cleanSQL(sql) {
  sql = sql.replace(/```/g, '');
  sql = fixWhenSpacing(sql);
  sql = fixInnerAs(sql);
  sql = fixParenAs(sql);
  sql = fixSelectWrapper(sql);
  sql = fixIllegalTuples(sql);

  // 💡 处理注释屏蔽和字段名修复
  const { sql: sqlNoComment, commentMap } = wrapComments(sql);
  let fixed = fixFieldNames(sqlNoComment);
  fixed = unwrapComments(fixed, commentMap);

  return fixed.trim();
}


// 提取 SQL 并清洗
function extractAndFixSQL(text) {
  const matches = [];
  let match;
  while ((match = sqlRegex.exec(text)) !== null) {
    let sql = match[1].trim();
    if (!sql.endsWith(';')) sql += ';';
    matches.push(cleanSQL(sql));
  }
  return matches;
}

const cleaned = extractAndFixSQL(inputText);

return cleaned.length > 0
  ? { valid: true, sqlStatements: cleaned, message: `✅ SQL语句清洗完成，共修复 ${cleaned.length} 条。` }
  : { valid: false, message: '❌ 未提取到 SQL 语句，请检查格式。' };

const answer = $input.first().json.choices[0].message.content;

// ✅ 1. 新增：获取外层工作流传进来的 chatInput
const chatInput = $('When Executed by Another Workflow').last().json.chatInput;

// 替换所有单引号为 \' 防止 SQL 插入失败
const escapeSql = (text) => {
  if (typeof text !== 'string') return text;
  return text.replace(/'/g, "\\'");
};

// 清洗 SQL：修复常见拼接错误
const cleanSql = (sqlText) => {
  if (typeof sqlText !== 'string') return sqlText;
  return sqlText
    .replace(/ASCLIMIT/gi, 'ASC LIMIT')  // 修复常见拼接错误
    .replace(/;\s*$/, '')                // 去除末尾分号
    .trim();
};

// 从 sql 节点中取出 SQL 原文
const rawSql = $('sql').first().json.sql;

return {
  json: {
    answer: escapeSql(answer),
    sql: escapeSql(cleanSql(rawSql)),      // ✅ 清洗 + 转义后输出
    safe_question: escapeSql(chatInput)    // ✅ 2. 新增：输出转义后的提问内容
  }
};
